// Inicializar identificadores de sesión sin estado e idempotencia
const body = $input.first().json.body || $input.first().json;

if (!body.contractText) {
  throw new Error('El campo "contractText" es requerido para iniciar la auditoría.');
}

const auditId = body.auditId || ('audit_' + Math.random().toString(36).substring(2, 12));
const executionId = $execution.id || 'exec_' + Date.now();

// Task 1 Payload: Extractor
const extractorTaskId = 'task_ext_' + Math.random().toString(36).substring(2, 9);
const extractorPayload = {
  taskId: extractorTaskId,
  auditId: auditId,
  executionId: executionId,
  targetAgent: 'EXTRACTOR',
  timestamp: new Date().toISOString(),
  constraints: {
    timeoutMs: 30000,
    maxRetries: 3,
    jurisdictionFallback: body.jurisdiction || 'Delaware, USA',
    strictJsonOnly: true
  },
  inputData: {
    rawContractText: body.contractText,
    documentType: body.documentType || 'MASTER_SERVICES_AGREEMENT',
    targetClauses: [
      'INDEMNIFICATION',
      'LIMITATION_OF_LIABILITY',
      'JURISDICTION_AND_GOVERNING_LAW',
      'TERMINATION'
    ]
  }
};

return [{
  json: {
    auditId,
    executionId,
    originalBody: body,
    extractorPayload
  }
}];

// GATEKEEPER 1: Validador de Esquema Extractor
const item = $input.first().json;
const out = item.outputData || item;
const errors = [];

if (!out || out.status !== 'SUCCESS') {
  errors.push('Status must be SUCCESS');
}
if (!Array.isArray(out.clauses)) {
  errors.push('Clauses must be an array');
} else {
  out.clauses.forEach((c, idx) => {
    if (!c.clauseId) errors.push(`Clause[${idx}] missing clauseId`);
    if (!c.clauseType) errors.push(`Clause[${idx}] missing clauseType`);
    if (!c.verbatimText) errors.push(`Clause[${idx}] missing verbatimText`);
  });
}

if (errors.length > 0) {
  return [{
    json: {
      isValid: false,
      gatekeeperError: {
        status: 'ERROR',
        stage: 'EXTRACTOR',
        errorCode: 'SCHEMA_VALIDATION_FAILED',
        message: errors.join('; '),
        timestamp: new Date().toISOString()
      }
    }
  }];
}

return [{
  json: {
    isValid: true,
    extractedData: out
  }
}];

// Preparar TaskPayload para el Analista de Riesgo
const extracted = $json.extractedData;
const prev = $('Init & Build TaskPayload').first().json;

const riskTaskId = 'task_risk_' + Math.random().toString(36).substring(2, 9);

return [{
  json: {
    taskId: riskTaskId,
    auditId: prev.auditId,
    executionId: prev.executionId,
    targetAgent: 'RISK_ANALYZER',
    timestamp: new Date().toISOString(),
    constraints: {
      timeoutMs: 35000,
      maxRetries: 3,
      strictJsonOnly: true
    },
    inputData: {
      governingJurisdiction: prev.originalBody.jurisdiction || 'Delaware, USA',
      applicableLaw: prev.originalBody.applicableLaw || 'Corporate & Commercial',
      clausesToEvaluate: extracted.clauses,
      partyAudited: 'CLIENT'
    },
    extractedSnapshot: extracted
  }
}];

// GATEKEEPER 2: Validador de Esquema Analista de Riesgo
const item = $input.first().json;
const out = item.outputData || item;
const errors = [];

if (!out || out.status !== 'SUCCESS') errors.push('Status must be SUCCESS');
if (typeof out.overallContractRiskScore !== 'number') errors.push('overallContractRiskScore must be number');
if (!Array.isArray(out.assessments)) {
  errors.push('assessments must be an array');
} else {
  out.assessments.forEach((a, idx) => {
    if (!a.clauseId) errors.push(`Assessment[${idx}] missing clauseId`);
    if (!a.severity) errors.push(`Assessment[${idx}] missing severity`);
    if (typeof a.riskScore !== 'number') errors.push(`Assessment[${idx}] riskScore must be number`);
  });
}

if (errors.length > 0) {
  return [{
    json: {
      isValid: false,
      gatekeeperError: {
        status: 'ERROR',
        stage: 'RISK_ANALYZER',
        errorCode: 'SCHEMA_VALIDATION_FAILED',
        message: errors.join('; '),
        timestamp: new Date().toISOString()
      }
    }
  }];
}

return [{
  json: {
    isValid: true,
    riskData: out
  }
}];

// Preparar Tareas de Mitigación solo para cláusulas HIGH o CRITICAL
const risk = $json.riskData;
const prevRiskTask = $('Build Risk TaskPayload').first().json;
const extractedClauses = prevRiskTask.extractedSnapshot.clauses;

const highRiskAssessments = risk.assessments.filter(a => a.severity === 'HIGH' || a.severity === 'CRITICAL');

if (highRiskAssessments.length === 0) {
  return [{
    json: {
      hasMitigationTasks: false,
      riskReport: risk,
      mitigationProposals: []
    }
  }];
}

// Tomamos la cláusula más crítica para mitigación inmediata
const topRisk = highRiskAssessments[0];
const matchedClause = extractedClauses.find(c => c.clauseId === topRisk.clauseId) || extractedClauses[0];

const mitTaskId = 'task_mit_' + Math.random().toString(36).substring(2, 9);

return [{
  json: {
    hasMitigationTasks: true,
    taskId: mitTaskId,
    auditId: prevRiskTask.auditId,
    executionId: prevRiskTask.executionId,
    targetAgent: 'MITIGATION_WRITER',
    timestamp: new Date().toISOString(),
    constraints: { timeoutMs: 30000, maxRetries: 3, strictJsonOnly: true },
    inputData: {
      clauseId: topRisk.clauseId,
      clauseType: topRisk.clauseType,
      verbatimText: matchedClause.verbatimText,
      riskAssessment: {
        severity: topRisk.severity,
        riskScore: topRisk.riskScore,
        rationale: topRisk.legalExposureRationale
      },
      advocacyPosition: 'DEFENSIVE'
    },
    riskSnapshot: risk
  }
}];

// GATEKEEPER 3 & Consolidación Final
const rawMit = $input.first().json;
const mitOutput = rawMit.outputData || rawMit;
const prevMit = $('Build Mitigation TaskPayload').first().json;

const finalReport = {
  auditId: prevMit.auditId,
  status: 'AUDIT_COMPLETED_SUCCESSFULLY',
  overallContractRiskScore: prevMit.riskSnapshot.overallContractRiskScore,
  dominantRiskFactor: prevMit.riskSnapshot.dominantRiskFactor,
  assessments: prevMit.riskSnapshot.assessments,
  mitigations: mitOutput.proposals || [],
  completedAt: new Date().toISOString()
};

return [{ json: finalReport }];

// Manejador Central de Dead-Letter Queue (DLQ)
const errorContext = $input.first().json.gatekeeperError || $input.first().json;

return [{
  json: {
    status: 'AUDIT_FAILED_ROUTED_TO_DLQ',
    error: errorContext,
    remediationAction: 'Stored in task_executions as DLQ_REVISE. Alert dispatched.',
    dispatchedAt: new Date().toISOString()
  }
}];
